question.answer:
import math


def tins_needed(area, coverage):
    return math.ceil(area / coverage)


def whole_metres(length):
    return math.floor(length)


def rounded_units(value):
    return round(value)


def line_total(unit_price, quantity):
    return round(unit_price * quantity, 2)

