question.answer:
import math
def split_shift(total, workers): return total // workers, total % workers
def division_report(): print(f"7 / 2 = {7 / 2}") print(f"7 // 2 = {7 // 2}") print(f"-7 // 2 = {-7 // 2} Java gives -3") print(f"-7 % 2 = {-7 % 2} Java gives -1") print(f"int(-7 / 2) = {int(-7 / 2)} Java truncation")
def rounding_report(): print(f"round(0.5) = {round(0.5)} Java Math.round gives 1") print(f"round(1.5) = {round(1.5)} Java Math.round gives 2") print(f"round(2.5) = {round(2.5)} Java Math.round gives 3")
def float_report(): print(f"0.1 + 0.2 = {0.1 + 0.2:.17f}") print(f"== 0.3 = {0.1 + 0.2 == 0.3}") print(f"math.isclose = {math.isclose(0.1 + 0.2, 0.3)}")
def big_power(): return 2 ** 100

